command:
$codePath = "$env:LOCALAPPDATA\Programs\Microsoft VS Code\bin\code.cmd"
if (Test-Path $codePath) { & $codePath --disable-extension GitHub.copilot; & $codePath --disable-extension GitHub.copilot-chat }
Write-Host 'done'

$tasks = @('Lenovo UDC Lazy Deployment','Lenovo UDC Maintainance Task','Lenovo UDC Monitor','McAfee Sync Agent Pilot','Office Actions Server','Office Background Push Maintenance','Office Feature Updates','Office Feature Updates Logon','Office Performance Monitor','Office Startup Maintenance','Office ClickToRun Service Monitor')
foreach ($t in $tasks) { try { Disable-ScheduledTask -TaskName $t -ErrorAction Stop | Out-Null; Write-Host "Disabled: $t" } catch { Write-Host "Skip: $t" } }
Write-Host 'done'
